+import { useState } from "react";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import { Label } from "@/components/ui/label";
+import type { RFQ, RFQItem } from "@/types/api";
+
+interface RFQFormProps {
+  rfq?: Partial<RFQ>;
+  items?: RFQItem[];
+  onSave: (data: { title: string; notes?: string }) => void;
+  onCancel: () => void;
+  onAddItem?: (item: { description: string; quantity: number; unit: string }) => void;
+  onRemoveItem?: (itemId: string) => void;
+}
+
+export function RFQForm({ rfq, items = [], onSave, onCancel, onAddItem, onRemoveItem }: RFQFormProps) {
+  const [title, setTitle] = useState(rfq?.title ?? "");
+  const [notes, setNotes] = useState(rfq?.notes ?? "");
+  const [newItemDesc, setNewItemDesc] = useState("");
+  const [newItemQty, setNewItemQty] = useState("");
+  const [newItemUnit, setNewItemUnit] = useState("Nos");
+
+  const handleSubmit = (e: React.FormEvent) => {
+    e.preventDefault();
+    onSave({ title, notes: notes || undefined });
+  };
+
+  const handleAddItem = () => {
+    if (onAddItem && newItemDesc && newItemQty) {
+      onAddItem({ description: newItemDesc, quantity: parseFloat(newItemQty), unit: newItemUnit });
+      setNewItemDesc("");
+      setNewItemQty("");
+    }
+  };
+
+  return (
+    <form onSubmit={handleSubmit} className="space-y-4">
+      <Card>
+        <CardHeader>
+          <CardTitle>{rfq?.id ? "Edit RFQ" : "Create RFQ"}</CardTitle>
+        </CardHeader>
+        <CardContent className="space-y-4">
+          <div>
+            <Label htmlFor="title">Title</Label>
+            <Input
+              id="title"
+              value={title}
+              onChange={(e) => setTitle(e.target.value)}
+              placeholder="RFQ for HVAC materials"
+              required
+            />
+          </div>
+          <div>
+            <Label htmlFor="notes">Notes</Label>
+            <Input
+              id="notes"
+              value={notes}
+              onChange={(e) => setNotes(e.target.value)}
+              placeholder="Additional notes..."
+            />
+          </div>
+
+          {onAddItem && (
+            <div className="space-y-2">
+              <Label>Items</Label>
+              {items.map((item, idx) => (
+                <div key={item.id || idx} className="flex items-center gap-2">
+                  <span className="flex-1">{item.description}</span>
+                  <span className="text-sm text-muted-foreground">{item.quantity} {item.unit}</span>
+                  {onRemoveItem && (
+                    <Button type="button" variant="ghost" size="sm" onClick={() => onRemoveItem(item.id)}>
+                      Remove
+                    </Button>
+                  )}
+                </div>
+              ))}
+              <div className="flex items-end gap-2">
+                <div className="flex-1">
+                  <Label className="text-xs">Description</Label>
+                  <Input
+                    value={newItemDesc}
+                    onChange={(e) => setNewItemDesc(e.target.value)}
+                    placeholder="Item description"
+                  />
+                </div>
+                <div className="w-24">
+                  <Label className="text-xs">Qty</Label>
+                  <Input
+                    type="number"
+                    value={newItemQty}
+                    onChange={(e) => setNewItemQty(e.target.value)}
+                    placeholder="0"
+                  />
+                </div>
+                <div className="w-20">
+                  <Label className="text-xs">Unit</Label>
+                  <Input
+                    value={newItemUnit}
+                    onChange={(e) => setNewItemUnit(e.target.value)}
+                    placeholder="Nos"
+                  />
+                </div>
+                <Button type="button" variant="outline" onClick={handleAddItem}>Add</Button>
+              </div>
+            </div>
+          )}
+
+          <div className="flex justify-end gap-2">
+            <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
+            <Button type="submit">{rfq?.id ? "Update" : "Create"} RFQ</Button>
+          </div>
+        </CardContent>
+      </Card>
+    </form>
+  );
+}
