+import { useState } from "react";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import { Label } from "@/components/ui/label";
+
+interface RFQResponseFormProps {
+  onSubmit: (data: {
+    vendor_id: string;
+    unit_price?: number;
+    delivery_days?: number;
+    validity_days?: number;
+    notes?: string;
+  }) => void;
+  onCancel: () => void;
+  onSelectVendor?: () => void;
+}
+
+export function RFQResponseForm({ onSubmit, onCancel, onSelectVendor }: RFQResponseFormProps) {
+  const [vendorId, setVendorId] = useState("");
+  const [unitPrice, setUnitPrice] = useState("");
+  const [deliveryDays, setDeliveryDays] = useState("");
+  const [validityDays, setValidityDays] = useState("");
+  const [notes, setNotes] = useState("");
+
+  const handleSubmit = (e: React.FormEvent) => {
+    e.preventDefault();
+    onSubmit({
+      vendor_id: vendorId,
+      unit_price: unitPrice ? parseFloat(unitPrice) : undefined,
+      delivery_days: deliveryDays ? parseInt(deliveryDays) : undefined,
