+
+          <div className="grid grid-cols-2 gap-4">
+            <div>
+              <Label htmlFor="delivery_days">Delivery Days</Label>
+              <Input
+                id="delivery_days"
+                type="number"
+                value={deliveryDays}
+                onChange={(e) => setDeliveryDays(e.target.value)}
