+              placeholder="Additional notes..."
+            />
+          </div>
+
+          <div className="flex justify-end gap-2">
+            <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
+            <Button type="submit">Submit Response</Button>
+          </div>
+        </CardContent>
