import { NewAgreementPage } from "@/pages/NewAgreementPage";
import { NewTokenPage } from "@/pages/NewTokenPage";
import { NewDRNPage } from "@/pages/NewDRNPage";
import { NewTimeLogPage } from "@/pages/NewTimeLogPage";
import { NewSustainabilityPage } from "@/pages/NewSustainabilityPage";
import { ConvertInquiryPage } from "@/pages/ConvertInquiryPage";
import { InquiryDetailPage } from "@/pages/InquiryDetailPage";
import { AgreementDetailPage } from "@/pages/AgreementDetailPage";
import { TokenDetailPage } from "@/pages/TokenDetailPage";
import { DRNDetailPage } from "@/pages/DRNDetailPage";
import { TimeLogDetailPage } from "@/pages/TimeLogDetailPage";
import { SustainabilityDetailPage } from "@/pages/SustainabilityDetailPage";
import { MarketingPage } from "@/pages/MarketingPage";
import { HRPage } from "@/pages/HRPage";
import { RnDPage } from "@/pages/RnDPage";
import { CRMPage } from "@/pages/CRMPage";

function App() {
  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route
        element={
          <ProtectedRoute>
            <AppShell />
          </ProtectedRoute>
        }
      >
        <Route path="/dashboard" element={<DashboardPage />} />
        <Route
          path="/users"
          element={
            <ProtectedRoute requiredRole="admin">
              <UsersPage />
            </ProtectedRoute>
          }
        />
        <Route path="/clients" element={<ClientsPage />} />
        <Route path="/clients/:id" element={<ClientDetailPage />} />
        <Route path="/clients/new" element={<NewClientPage />} />
        <Route path="/projects" element={<ProjectsPage />} />
        <Route path="/projects/:id" element={<ProjectDetailPage />} />
        <Route path="/projects/new" element={<NewProjectPage />} />
        <Route path="/vendors" element={<VendorsPage />} />
        <Route path="/materials" element={<MaterialsPage />} />
        <Route path="/tasks/my" element={<MyTasksPage />} />
        <Route path="/inquiries" element={<InquiriesPage />} />
        <Route path="/inquiries/new" element={<NewInquiryPage />} />
        <Route path="/inquiries/:id/convert" element={<ConvertInquiryPage />} />
        <Route path="/inquiries/:id" element={<InquiryDetailPage />} />
        <Route path="/agreements" element={<AgreementsPage />} />
        <Route path="/agreements/new" element={<NewAgreementPage />} />
        <Route path="/agreements/:id" element={<AgreementDetailPage />} />
        <Route path="/tokens" element={<TokensPage />} />
        <Route path="/tokens/new" element={<NewTokenPage />} />
        <Route path="/tokens/:id" element={<TokenDetailPage />} />
        <Route path="/drns" element={<DRNsPage />} />
        <Route path="/drns/new" element={<NewDRNPage />} />
        <Route path="/drns/:id" element={<DRNDetailPage />} />
        <Route path="/time-logs" element={<TimeLogsPage />} />
        <Route path="/time-logs/new" element={<NewTimeLogPage />} />
        <Route path="/time-logs/:id" element={<TimeLogDetailPage />} />
        <Route path="/sustainability" element={<SustainabilityPage />} />
        <Route path="/sustainability/new" element={<NewSustainabilityPage />} />
        <Route path="/sustainability/:id" element={<SustainabilityDetailPage />} />
        <Route path="/marketing" element={<MarketingPage />} />
        <Route path="/hr" element={<HRPage />} />
        <Route path="/rnd" element={<RnDPage />} />
        <Route path="/crm" element={<CRMPage />} />
        <Route path="/" element={<Navigate to="/dashboard" replace />} />
      </Route>
      <Route path="*" element={<Navigate to="/dashboard" replace />} />
    </Routes>
  );
}

export default App;

import { NavLink } from "react-router-dom";
import { cn } from "@/lib/utils";
import { LayoutDashboard, Users, Building2, FolderKanban, Diamond, Package, Truck, ClipboardList, HelpCircle, FileText, Coins, FileCheck, Clock, Leaf, Megaphone, UserCog, FlaskConical, MessageSquareWarning } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";

const navItems = [
  { to: "/dashboard", icon: LayoutDashboard, label: "Dashboard" },
  { to: "/clients", icon: Building2, label: "Clients" },
  { to: "/projects", icon: FolderKanban, label: "Projects" },
  { to: "/inquiries", icon: HelpCircle, label: "Inquiries" },
  { to: "/agreements", icon: FileText, label: "Agreements" },
  { to: "/tokens", icon: Coins, label: "Tokens" },
  { to: "/drns", icon: FileCheck, label: "DRNs" },
  { to: "/time-logs", icon: Clock, label: "Time Logging" },
  { to: "/sustainability", icon: Leaf, label: "Sustainability" },
  { to: "/marketing", icon: Megaphone, label: "Marketing" },
  { to: "/rnd", icon: FlaskConical, label: "R&D" },
  { to: "/crm", icon: MessageSquareWarning, label: "CRM" },
  { to: "/hr", icon: UserCog, label: "HR" },
  { to: "/vendors", icon: Truck, label: "Vendors" },
  { to: "/materials", icon: Package, label: "Materials" },
  { to: "/tasks/my", icon: ClipboardList, label: "My Tasks" },
  { to: "/users", icon: Users, label: "Team", adminOnly: true },
];

export function Sidebar() {
  const { user } = useAuth();

  return (
    <aside className="w-64 border-r border-slate-800 bg-slate-950 flex flex-col">
      <div className="flex h-14 items-center border-b border-slate-800 px-4 gap-2">
        <Diamond className="h-5 w-5 text-emerald-400" />
        <span className="font-bold text-sm tracking-tight text-white">SWA ERP</span>
        <span className="ml-auto text-[10px] font-mono text-slate-600 bg-slate-900 px-1.5 py-0.5 rounded border border-slate-800">v2.0</span>
      </div>
      <nav className="p-3 space-y-0.5 flex-1">
        {navItems.map((item) => {
          if (item.adminOnly && user?.role !== "admin") {
            return null;
          }
          return (
            <NavLink
              key={item.to}
              to={item.to}
              className={({ isActive }) =>
                cn(
                  "flex items-center gap-3 rounded-md px-3 py-2 text-sm font-medium transition-all",
                  isActive
                    ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"
                    : "text-slate-400 hover:bg-slate-900 hover:text-slate-200"
                )
              }
            >
              <item.icon className="h-4 w-4" />
              {item.label}
            </NavLink>
          );
        })}
      </nav>
      <div className="p-3 border-t border-slate-800">
        <div className="flex items-center gap-2 px-3 py-2">
          <div className="h-6 w-6 rounded-full bg-emerald-500/20 flex items-center justify-center">
            <span className="text-[10px] font-bold text-emerald-400 uppercase">{user?.name?.[0] || 'U'}</span>
          </div>
          <div className="flex flex-col min-w-0">
            <span className="text-xs font-medium text-slate-300 truncate">{user?.name || 'User'}</span>
            <span className="text-[10px] text-slate-500 uppercase">{user?.role || 'viewer'}</span>
          </div>
        </div>
      </div>
    </aside>
  );
}

