import {
  ClientFeedback,
  ClientComplaint,
  ClientFeedbackListResponse,
  ClientComplaintListResponse,
  ClientFeedbackCreate,
  ClientComplaintCreate,
} from "@/types/crm";

export type {
  ClientFeedback,
  ClientComplaint,
  ClientFeedbackListResponse,
  ClientComplaintListResponse,
  ClientFeedbackCreate,
  ClientComplaintCreate,
};

const API_BASE_URL = "/api";

class CrmApiError extends Error {
  constructor(public status: number, public body: unknown) {
    super(`CRM API Error: ${status}`);
    this.name = "CrmApiError";
  }
}

async function crmRequest<T>(
  path: string,
  options: RequestInit = {}
): Promise<T> {
  const token = localStorage.getItem("access_token");
  const headers: Record<string, string> = {
    ...(options.headers as Record<string, string>),
  };
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  if (!headers["Content-Type"] && !(options.body instanceof FormData)) {
    headers["Content-Type"] = "application/json";
  }

  let response = await fetch(path, { ...options, headers });

  if (response.status === 401) {
    const refresh = localStorage.getItem("refresh_token");
    if (refresh) {
      try {
        const refreshResponse = await fetch(`${API_BASE_URL}/auth/refresh`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ refresh_token: refresh }),
        });
        if (refreshResponse.ok) {
          const tokens = await refreshResponse.json();
          localStorage.setItem("access_token", tokens.access_token);
          headers["Authorization"] = `Bearer ${tokens.access_token}`;
          response = await fetch(path, { ...options, headers });
        } else {
          localStorage.removeItem("access_token");
          localStorage.removeItem("refresh_token");
          window.location.href = "/login";
          throw new CrmApiError(401, null);
        }
      } catch {
        localStorage.removeItem("access_token");
        localStorage.removeItem("refresh_token");
        window.location.href = "/login";
        throw new CrmApiError(401, null);
      }
    }
  }

  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new CrmApiError(response.status, body);
  }

  return response.json();
}

export const crmApi = {
  listClientFeedback: async (
    params?: { page?: number; page_size?: number; q?: string }
  ): Promise<ClientFeedbackListResponse> => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    const query = searchParams.toString();
    const endpoint = `/api/client-feedback${query ? `?${query}` : ""}`;
    const response = await crmRequest<ClientFeedbackListResponse>(endpoint, {
      method: "GET",
    });
    return response;
  },

  createClientFeedback: async (
    data: ClientFeedbackCreate
  ): Promise<ClientFeedback> => {
    const endpoint = `/api/client-feedback`;
    const response = await crmRequest<ClientFeedback>(endpoint, {
      method: "POST",
      body: JSON.stringify(data),
    });
    return response;
  },

  getClientFeedback: async (id: string): Promise<ClientFeedback> => {
    const endpoint = `/api/client-feedback/${id}`;
    const response = await crmRequest<ClientFeedback>(endpoint);
    return response;
  },

  updateClientFeedback: async (
    id: string,
    data: Partial<ClientFeedbackCreate>
  ): Promise<ClientFeedback> => {
    const endpoint = `/api/client-feedback/${id}`;
    const response = await crmRequest<ClientFeedback>(endpoint, {
      method: "PATCH",
      body: JSON.stringify(data),
    });
    return response;
  },

  deleteClientFeedback: async (id: string): Promise<void> => {
    const endpoint = `/api/client-feedback/${id}`;
    await crmRequest<void>(endpoint, {
      method: "DELETE",
    });
  },

  listClientComplaints: async (
    params?: { page?: number; page_size?: number; q?: string; severity?: string }
  ): Promise<ClientComplaintListResponse> => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    if (params?.severity) searchParams.set("severity", params.severity);
    const query = searchParams.toString();
    const endpoint = `/api/client-complaints${query ? `?${query}` : ""}`;
    const response = await crmRequest<ClientComplaintListResponse>(endpoint, {
      method: "GET",
    });
    return response;
  },

  createClientComplaint: async (
    data: ClientComplaintCreate
  ): Promise<ClientComplaint> => {
    const endpoint = `/api/client-complaints`;
    const response = await crmRequest<ClientComplaint>(endpoint, {
      method: "POST",
      body: JSON.stringify(data),
    });
    return response;
  },

  getClientComplaint: async (id: string): Promise<ClientComplaint> => {
    const endpoint = `/api/client-complaints/${id}`;
    const response = await crmRequest<ClientComplaint>(endpoint);
    return response;
  },

  updateClientComplaint: async (
    id: string,
    data: Partial<ClientComplaintCreate>
  ): Promise<ClientComplaint> => {
    const endpoint = `/api/client-complaints/${id}`;
    const response = await crmRequest<ClientComplaint>(endpoint, {
      method: "PATCH",
      body: JSON.stringify(data),
    });
    return response;
  },

  deleteClientComplaint: async (id: string): Promise<void> => {
    const endpoint = `/api/client-complaints/${id}`;
    await crmRequest<void>(endpoint, {
      method: "DELETE",
    });
  },
};

